(function () { 'use strict'; var OPEN = 'is-open'; var uid = 0; function init() { var navs = document.querySelectorAll('.lp-services-nav'); for (var n = 0; n < navs.length; n++) { enhance(navs[n]); } collapseServicesBar(); } function collapseServicesBar() { var bar = document.querySelector('.lp-header-services'); if (!bar) { return; } var label = bar.querySelector('.lp-services-label'); var list = bar.querySelector('.lp-services-nav'); if (!label || !list) { return; } if (!list.id) { list.id = 'lp-services-list'; } var toggle = document.createElement('button'); toggle.type = 'button'; toggle.className = 'lp-services-label lp-services-toggle'; toggle.setAttribute('aria-expanded', 'false'); toggle.setAttribute('aria-controls', list.id); toggle.innerHTML = label.textContent + '<span class="lp-caret" aria-hidden="true"></span>'; label.replaceWith(toggle); bar.classList.add('lp-js'); toggle.addEventListener('click', function () { var open = bar.classList.toggle('is-open'); toggle.setAttribute('aria-expanded', open ? 'true' : 'false'); }); } function enhance(nav) { nav.classList.add('lp-js'); var groups = nav.querySelectorAll('.lp-has-sub'); for (var i = 0; i < groups.length; i++) { wire(nav, groups[i]); } document.addEventListener('click', function (e) { if (!nav.contains(e.target)) { closeAll(nav); } }); nav.addEventListener('keydown', function (e) { if (e.key === 'Escape' || e.key === 'Esc') { var open = nav.querySelector('.lp-has-sub.' + OPEN); if (open) { var toggle = open.querySelector('.lp-subnav-toggle'); close(open); if (toggle) { toggle.focus(); } } } }); } function wire(nav, group) { var panel = group.querySelector('.lp-subnav'); if (!panel) { return; } if (!panel.id) { panel.id = 'lp-subnav-' + (++uid); } panel.setAttribute('role', 'region'); var heading = group.querySelector('a, .lp-nav-head'); var name = heading ? heading.textContent.trim() : 'menu'; panel.setAttribute('aria-label', name); var toggle = document.createElement('button'); toggle.type = 'button'; toggle.className = 'lp-subnav-toggle'; toggle.setAttribute('aria-expanded', 'false'); toggle.setAttribute('aria-controls', panel.id); toggle.setAttribute('aria-label', 'Toggle ' + name); toggle.innerHTML = '<span class="lp-caret" aria-hidden="true"></span>'; if (heading && heading.nextSibling) { group.insertBefore(toggle, heading.nextSibling); } else { group.appendChild(toggle); } toggle.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); if (group.classList.contains(OPEN)) { close(group); } else { closeAll(nav); open(group); } }); } function open(group) { group.classList.add(OPEN); setState(group, true); } function close(group) { group.classList.remove(OPEN); setState(group, false); } function closeAll(nav) { var open = nav.querySelectorAll('.lp-has-sub.' + OPEN); for (var i = 0; i < open.length; i++) { close(open[i]); } } function setState(group, expanded) { var toggle = group.querySelector('.lp-subnav-toggle'); if (toggle) { toggle.setAttribute('aria-expanded', expanded ? 'true' : 'false'); } } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); } })();